{"term": "carnal", "lang": "en", "script": "latin", "romanization": null, "category": "religious_moral_status", "subcategory": "desire_physical", "concept": "carnal_desire", "is_novel_concept": false, "register": "moral_religious", "crude": 22, "technical": 15, "recognition_pct_current": 78, "recognition_pct_peak": 78, "peak_year": null, "regional": null, "definition": "Relating to the physical body and its desires, especially sexual appetite, typically contrasted with the spiritual.", "english_term": "carnal", "english_translation_quality": "direct", "notes": "'Carnal knowledge' is a legal/archaic term for sexual intercourse; strong religious framing positions carnal desire as morally suspect; from Latin caro (flesh)."}
{"term": "wanton", "lang": "en", "script": "latin", "romanization": null, "category": "archaic_literary", "subcategory": "sexual_unrestrained", "concept": "wanton_behavior", "is_novel_concept": false, "register": "archaic", "crude": 28, "technical": 8, "recognition_pct_current": 55, "recognition_pct_peak": 72, "peak_year": null, "regional": null, "definition": "Sexually uninhibited or promiscuous; lewd and lascivious (archaic/literary adjective or noun for a licentious person).", "english_term": "wanton", "english_translation_quality": "direct", "notes": "Also means deliberate cruelty unrelated to sex (wanton destruction); gender-neutral historically but often applied to women; found in Shakespeare and Chaucer."}
