{"term": "debauched", "lang": "en", "script": "latin", "romanization": null, "category": "desire_arousal_descriptors", "subcategory": "sexual_excess", "concept": "debauchery", "is_novel_concept": false, "register": "literary", "crude": 28, "technical": 10, "recognition_pct_current": 68, "recognition_pct_peak": 68, "peak_year": null, "regional": null, "definition": "Morally corrupted by overindulgence in sensual pleasures, particularly sex, alcohol, and related excess.", "english_term": "debauched", "english_translation_quality": "direct", "notes": "Implies broader dissolution beyond sex alone; 'debauched lifestyle' typically connotes multiple vices; from French débaucher (to lure away from duty)."}
