{"term": "amorous", "lang": "en", "script": "latin", "romanization": null, "category": "desire_arousal_descriptors", "subcategory": "romantic_desire", "concept": "amorous_feeling", "is_novel_concept": false, "register": "literary", "crude": 8, "technical": 8, "recognition_pct_current": 72, "recognition_pct_peak": 72, "peak_year": null, "regional": null, "definition": "Showing or feeling romantic or sexual love; inclined toward love and desire.", "english_term": "amorous", "english_translation_quality": "direct", "notes": "Blends romantic and sexual desire without cleanly separating them; 'amorous advances' is a common phrase; genteel register; from Latin amor (love)."}
